package dev.industrialtechnology.builder;

import cpw.mods.fml.common.*;
import cpw.mods.fml.common.event.*;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import cpw.mods.fml.common.gameevent.TickEvent;
import cpw.mods.fml.relauncher.Side;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import net.minecraft.block.Block;
import net.minecraft.entity.player.*;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.*;
import net.minecraft.world.*;
import net.minecraftforge.common.*;
import net.minecraftforge.common.util.*;
import net.minecraftforge.event.world.BlockEvent;

@Mod(modid="industrialtech_carpenter_builder_checks",name="Carpenter building checks",version="1",dependencies="required-after:industrialtech")
public final class CarpenterBuilderChecks {
    private int wait=25,phase,failed;private WorldServer w;private FakePlayer p;private ItemStack tool;private Block slope,technical;private final List<String> report=new ArrayList<String>();
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(!Boolean.getBoolean("industrialtech.carpenterBuilderTest"))return;if(e.getSide()==Side.CLIENT)dev.industrialtechnology.builder.client.CarpenterBuilderClientChecks.install();else FMLCommonHandler.instance().bus().register(this);}
    static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
    private interface Checked {void run() throws Exception;}
    void test(String text,Checked r){try{r.run();report.add("PASS: "+text);}catch(Throwable t){failed++;report.add("FAIL: "+text+" :: "+t);t.printStackTrace();}}
    public static NBTTagCompound raw(TileEntity t){NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);return n;}
    public static void configure(World w,int x,int y,int z,Block block,int shape,ItemStack cover,boolean decorate){
        w.setBlock(x,y,z,block,cover.getItemDamage(),2);TileEntity t=w.getTileEntity(x,y,z);NBTTagCompound n=raw(t);n.setInteger("cbMetadata",shape);n.setString("cbOwner","OriginalOwner");NBTTagList list=new NBTTagList();attr(list,6,cover);if(decorate){attr(list,13,new ItemStack(Items.dye,1,4));attr(list,21,new ItemStack(Items.glowstone_dust));n.setString("cbChiselDesign_6","chisel_0");}n.setTag("cbAttrList",list);t.readFromNBT(n);t.markDirty();w.markBlockForUpdate(x,y,z);
    }
    public static void attr(NBTTagList list,int slot,ItemStack item){NBTTagCompound n=new NBTTagCompound();item.writeToNBT(n);n.setByte("cbAttribute",(byte)slot);n.setString("cbUniqueId",Item.itemRegistry.getNameForObject(item.getItem()));list.appendTag(n);}
    private void reset(){BuilderService.cancel(p,false);for(int i=0;i<36;i++)p.inventory.mainInventory[i]=null;tool=new ItemStack(BuilderRegistry.stick);p.inventory.mainInventory[0]=tool;p.inventory.currentItem=0;p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);}
    private void select(int x,int y,int z){p.setSneaking(true);p.setPosition(x+.5,y+2,z-2);p.theItemInWorldManager.activateBlockOrUseItem(p,w,tool,x,y,z,1,.5F,.9F,.5F);p.setSneaking(false);check(BuilderCarpenters.selected(tool,BuilderData.material(tool)),"Template not selected");}
    private void stock(Block block,int n,ItemStack cover,boolean extras){p.inventory.mainInventory[1]=new ItemStack(block,n);p.inventory.mainInventory[2]=cover.copy();p.inventory.mainInventory[2].stackSize=n;if(extras){p.inventory.mainInventory[3]=new ItemStack(Items.dye,n,4);p.inventory.mainInventory[4]=new ItemStack(Items.glowstone_dust,n);}}
    private int count(Item item,int damage){int n=0;for(ItemStack s:p.inventory.mainInventory)if(s!=null&&s.getItem()==item&&s.getItemDamage()==damage)n+=s.stackSize;return n;}
    private void build(int x,int y,int z,int end,BuildMode mode){BuilderData.tag(tool).setByte("BuildMode",(byte)mode.ordinal());BuilderData.clear(tool);w.setBlock(x,y-1,z,Blocks.stone,0,2);w.setBlock(end,y-1,z,Blocks.stone,0,2);p.rotationYaw=180;p.setPosition(x+.5,y+2,z-2);BuilderService.click(p,tool,x,y-1,z,1);p.setPosition(end+.5,y+2,z-2);BuilderService.click(p,tool,end,y-1,z,1);for(int i=0;i<10&&BuilderService.active(p);i++){BuilderService.step();check(BuilderService.lastScans<=BuilderService.GLOBAL_SCAN&&BuilderService.lastAttempts<=BuilderService.GLOBAL_ATTEMPTS,"Builder budgets exceeded");}}
    public static final class Deny {boolean enabled=true;int count;@SubscribeEvent public void place(BlockEvent.PlaceEvent e){if(enabled){count++;e.setCanceled(true);}}}
    private int drops(){int n=0;for(Object o:w.loadedEntityList)if(o instanceof EntityItem)n+=((EntityItem)o).getEntityItem().stackSize;return n;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(phase==99||e.phase!=TickEvent.Phase.END||--wait>0)return;try{
        w=MinecraftServer.getServer().worldServerForDimension(0);for(int x=0;x<9;x++)for(int z=0;z<9;z++)w.getChunkFromChunkCoords(x,z);slope=Block.getBlockFromName("CarpentersBlocks:blockCarpentersSlope");technical=Block.getBlockFromName("chisel:technical");check(slope!=null&&technical!=null,"Real Carpenter's/Chisel required");p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("00000000-0000-0000-0000-000000001616"),"CarpChecks")){public void sendPlayerAbilities(){}public void addChatMessage(IChatComponent c){}};p.playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),p){public void sendPacket(net.minecraft.network.Packet packet){}};reset();
        if("restart".equals(System.getProperty("industrialtech.carpenterBuilderPhase"))){test("Fresh JVM retains copied shape, Chisel cover metadata and new per-block coordinates",()->{NBTTagCompound original=BuilderCarpenters.capture(w,24,70,24);for(int x=32;x<=36;x++){check(original.equals(BuilderCarpenters.capture(w,x,70,24)),"Appearance changed on restart");TileEntity t=w.getTileEntity(x,70,24);check(t.xCoord==x&&t.yCoord==70&&t.zCoord==24,"Original coordinates copied");}});test("A saved stick template still resolves by namespaced item IDs after restart",()->{NBTTagCompound n=net.minecraft.nbt.CompressedStreamTools.read(new java.io.File("carpenter-stick.dat"));ItemStack saved=ItemStack.loadItemStackFromNBT(n);check(BuilderCarpenters.read(saved,w)!=null,"Saved template lost");});finish();return;}
        test("Native sneak-right-click saves a covered rotated slope without changing any source NBT or orientation",()->{configure(w,24,70,24,slope,11,new ItemStack(technical,1,3),true);NBTTagCompound before=raw(w.getTileEntity(24,70,24));select(24,70,24);check(before.equals(raw(w.getTileEntity(24,70,24))),"Selection mutated original");check(BuilderCarpenters.label(tool,BuilderData.material(tool)).contains(" / "),"Cover name not visible");NBTTagCompound n=new NBTTagCompound();tool.writeToNBT(n);net.minecraft.nbt.CompressedStreamTools.write(n,new java.io.File("carpenter-stick.dat"));check(BuilderCarpenters.read(ItemStack.loadItemStackFromNBT(n),w)!=null,"Stick reload failed");check(before.equals(raw(w.getTileEntity(24,70,24))),"Cost normalization mutated original");});
        test("Survival line copies Chisel texture, shape, dye and illumination exactly while spending every material once",()->{stock(slope,5,new ItemStack(technical,1,3),true);NBTTagCompound before=raw(w.getTileEntity(24,70,24)),appearance=BuilderCarpenters.capture(w,24,70,24);build(32,70,24,36,BuildMode.LINE);for(int x=32;x<=36;x++){check(appearance.equals(BuilderCarpenters.capture(w,x,70,24)),"Wrong clone at "+x);NBTTagCompound n=raw(w.getTileEntity(x,70,24));check(!n.getString("cbOwner").equals("OriginalOwner")&&n.getInteger("x")==x,"Owner or coordinates copied");}check(count(Item.getItemFromBlock(slope),0)==0&&count(Item.getItemFromBlock(technical),3)==0&&count(Items.dye,4)==0&&count(Items.glowstone_dust,0)==0,"Material conservation failed");check(before.equals(raw(w.getTileEntity(24,70,24))),"Line altered source");});
        test("Canceled placement restores targets and refunds base blocks, covers, dye and illumination without item drops",()->{reset();select(24,70,24);stock(slope,3,new ItemStack(technical,1,3),true);Deny d=new Deny();MinecraftForge.EVENT_BUS.register(d);int before=drops();try{build(32,70,32,34,BuildMode.LINE);check(d.count>0,"No native placement event");for(int x=32;x<=34;x++)check(w.isAirBlock(x,70,32)&&w.getTileEntity(x,70,32)==null,"Canceled ghost tile");check(count(Item.getItemFromBlock(slope),0)==3&&count(Item.getItemFromBlock(technical),3)==3&&count(Items.dye,4)==3&&count(Items.glowstone_dust,0)==3&&drops()==before,"Canceled clone leaked or lost materials");}finally{d.enabled=false;MinecraftForge.EVENT_BUS.unregister(d);}});
        test("Missing covers stop the build without spending otherwise available Carpenter blocks",()->{reset();select(24,70,24);p.inventory.mainInventory[1]=new ItemStack(slope,4);build(32,70,40,35,BuildMode.LINE);check(w.isAirBlock(32,70,40)&&count(Item.getItemFromBlock(slope),0)==4&&!BuilderService.active(p),"Free cover or lost base");});
        test("Rotated log covers pay normal log items but preserve the cover axis, including the original source",()->{reset();configure(w,24,70,48,slope,4,new ItemStack(Blocks.log,1,8),false);NBTTagCompound before=raw(w.getTileEntity(24,70,48));select(24,70,48);stock(slope,3,new ItemStack(Blocks.log),false);build(32,70,48,34,BuildMode.LINE);for(int x=32;x<=34;x++)check(BuilderCarpenters.capture(w,24,70,48).equals(BuilderCarpenters.capture(w,x,70,48)),"Log axis rotated");check(count(Item.getItemFromBlock(Blocks.log),0)==0&&before.equals(raw(w.getTileEntity(24,70,48))),"Normalized wrong source or log payment");});
        test("All supported decorative Carpenter types retain their configured data despite a different player facing",()->{String[] names={"Block","Slope","Stairs","CollapsibleBlock","Barrier"};int[] shapes={6,34,18,1|(4<<3)|(8<<8)|(12<<13)|(16<<18),20};for(int i=0;i<names.length;i++){reset();Block b=Block.getBlockFromName("CarpentersBlocks:blockCarpenters"+names[i]);check(b!=null,"Missing type "+names[i]);int z=60+i*5;configure(w,24,70,z,b,shapes[i],new ItemStack(technical,1,5),false);select(24,70,z);stock(b,3,new ItemStack(technical,1,5),false);build(32,70,z,34,BuildMode.LINE);for(int x=32;x<=34;x++)check(BuilderCarpenters.capture(w,24,70,z).equals(BuilderCarpenters.capture(w,x,70,z)),"Changed shape "+names[i]);}});
        test("Occupied containers and existing Carpenter blocks remain untouched",()->{reset();select(24,70,24);p.theItemInWorldManager.setGameType(WorldSettings.GameType.CREATIVE);w.setBlock(33,70,88,Blocks.chest,0,2);configure(w,34,70,88,slope,8,new ItemStack(technical,1,9),false);NBTTagCompound before=raw(w.getTileEntity(34,70,88));build(32,70,88,35,BuildMode.LINE);check(w.getBlock(33,70,88)==Blocks.chest&&before.equals(raw(w.getTileEntity(34,70,88))),"Existing target altered");});
        test("A placement that would strip an adjacent Carpenter side cover is skipped",()->{reset();Block b=Block.getBlockFromName("CarpentersBlocks:blockCarpentersBlock");configure(w,24,70,96,b,0,new ItemStack(technical,1,3),false);select(24,70,96);p.theItemInWorldManager.setGameType(WorldSettings.GameType.CREATIVE);configure(w,33,70,96,b,0,new ItemStack(technical,1,5),false);TileEntity t=w.getTileEntity(33,70,96);NBTTagCompound n=raw(t);NBTTagList a=n.getTagList("cbAttrList",10);attr(a,4,new ItemStack(Blocks.wool,1,11));n.setTag("cbAttrList",a);t.readFromNBT(n);NBTTagCompound before=raw(t);build(32,70,96,32,BuildMode.LINE);check(w.isAirBlock(32,70,96)&&before.equals(raw(t)),"Neighbor side cover damaged");});
        test("Containers, doors, generic tile entities and malformed templates remain excluded",()->{check(!BuilderCarpenters.supported(Blocks.chest)&&!BuilderCarpenters.supported(Block.getBlockFromName("CarpentersBlocks:blockCarpentersSafe"))&&!BuilderCarpenters.supported(Block.getBlockFromName("CarpentersBlocks:blockCarpentersDoor")),"Unsafe type accepted");reset();select(24,70,24);BuilderData.tag(tool).getCompoundTag(BuilderCarpenters.TAG).setInteger("Shape",999999);check(BuilderCarpenters.read(tool,w)==null,"Malformed shape accepted");});
        test("Selecting an ordinary block clears the Carpenter template and retains ordinary placement",()->{reset();select(24,70,24);w.setBlock(24,70,104,Blocks.stone,0,2);p.setSneaking(true);p.setPosition(24.5,72,102);BuilderService.click(p,tool,24,70,104,1);p.setSneaking(false);check(!BuilderData.tag(tool).hasKey(BuilderCarpenters.TAG)&&BuilderData.material(tool).getItem()==Item.getItemFromBlock(Blocks.stone),"Stale template remained");p.inventory.mainInventory[1]=new ItemStack(Blocks.stone,3);build(32,70,104,34,BuildMode.LINE);for(int x=32;x<=34;x++)check(w.getBlock(x,70,104)==Blocks.stone,"Ordinary build regressed");});
        finish();
    }catch(Throwable t){failed++;report.add("FAIL: fixture "+t);t.printStackTrace();finish();}}
    private void finish(){report.add("Failed: "+failed);try{Files.write(Paths.get("carpenter-builder-"+System.getProperty("industrialtech.carpenterBuilderPhase","initial")+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}phase=99;MinecraftServer.getServer().initiateShutdown();}
}
